<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>

const int MOD = 1000000007;
const int MAXN = 3000010;

int p, k, t;
bool used[MAXN];

void dfs(int x) {
    std::vector<int> stack;
    stack.push_back(x);
    while (!stack.empty()) {
        int v = stack.back();
        stack.pop_back();
        if (used[v]) continue;
        used[v] = true;
        int to = (1LL * v * k) % p;
        if (!used[to]) {
            stack.push_back(to);
        }
    }
}

int main() {
    scanf("%d%d", &p, &k);
    for (int i = 0; i < p; ++i) {
        if (!used[i]) {
            ++t;
            dfs(i);
        }
    }
    long long ans = 1;
    int limit = t + (k == 1);
    for (int i = 1; i < limit; ++i) {
        ans = (ans * p) % MOD;
    }
    printf("%lld\n", ans);
    return 0;
}
